///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const sbmOptions = {
            id : "sbm_dts_TotalList",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_TotalList=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions2 = {
            id : "sbm_dts_NotiObjList",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_NotiObjList=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions3 = {
            id : "sbm_dts_Save",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
        // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        await scwin.listCdSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10905.onpageload" });
    }
};

