        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
        await scwin.listCdSync();
        await scwin.resetdts_Save();

        // frame.Provider("../").fn_search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10905.trs_Save_OnSuccess" });
