/**
 * @method
 * @name grd_TotalList_onheadcheckclick
 * @description grd_TotalList onheadcheckclick 이벤트
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.grd_TotalList_onheadcheckclick = function(col, colid, bCheck) {
    try {
        let gcnt = dts_TotalList.getRowCount();
        if (gcnt > 0) {
            grd_TotalList.Redraw = false;
            dts_TotalList.setBroadcast(false);
            for (let i = 1; i <= gcnt; i++) {
                if (bCheck === 1) {
                    dts_TotalList.setCellData(i, "CHK_FLAG", 'T');
                } else {
                    dts_TotalList.setCellData(i, "CHK_FLAG", 'F');
                }
            }
            dts_TotalList.setBroadcast(true, true);
            grd_TotalList.Redraw = true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10905.grd_TotalList_onheadcheckclick" });
    }
};

