/**
 * @method
 * @name save
 * @description 등록
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    // 등록
    let tmpInt = 1;
    if (!scwin.cntDatasetRowCheck(dts_TotalList)) {
        await $c.win.alert("등록할 체크사항이 없습니다.");
    } else {
        let msg = $c.stf.getMessageParam("MSG-A006", "등록");
        let res = window.confirm(msg);
        if (res) {
            dts_Save.setBroadcast(false);
            for (let i = 1; i <= dts_TotalList.getRowCount(); i++) {
                if (dts_TotalList.getCellData(i, "CHK_FLAG") === 'T') {
                    dts_Save.insertRow();
                    dts_Save.setCellData(tmpInt, "LIST_BZ_RSN_TP_CD", dts_TotalList.getCellData(i, "LIST_BZ_RSN_TP_CD"));
                    dts_Save.setCellData(tmpInt, "LIST_BZ_RSN_CD", dts_TotalList.getCellData(i, "LIST_BZ_RSN_CD"));
                    dts_Save.setCellData(tmpInt, "LIST_BZ_RSN_NM", dts_TotalList.getCellData(i, "LIST_BZ_RSN_NM"));
                    dts_Save.setCellData(tmpInt, "TRANSTR_EMP_NO", js_id);
                    dts_Save.setCellData(tmpInt, "USE_YN", 'Y');
                    tmpInt++;
                }
            }
            dts_Save.setBroadcast(true, true);
            trs_Save.KeyName = "toinb_dataid4";
            const sbmOptions = {
                id : "sbm_trs_Save",
                action : "/MktActNotice.do",
                ref : "dts_Save",
                target : "trs_Save=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    let tmpInt = 1;
    if (!scwin.cntDatasetRowCheck(dts_NotiObjList)) {
        await $c.win.alert("해제할 체크사항이 없습니다.");
    } else {
        let msg = $c.stf.getMessageParam("MSG-A006", "해제");
        let res = window.confirm(msg);
        if (res) {
            dts_Save.setBroadcast(false);
            for (let i = 1; i <= dts_NotiObjList.getRowCount(); i++) {
                if (dts_NotiObjList.getCellData(i, "CHK_FLAG") === 'T') {
                    dts_Save.insertRow();
                    dts_Save.setCellData(tmpInt, "LIST_BZ_RSN_TP_CD", dts_NotiObjList.getCellData(i, "LIST_BZ_RSN_TP_CD"));
                    dts_Save.setCellData(tmpInt, "LIST_BZ_RSN_CD", dts_NotiObjList.getCellData(i, "LIST_BZ_RSN_CD"));
                    dts_Save.setCellData(tmpInt, "LIST_BZ_RSN_NM", dts_NotiObjList.getCellData(i, "LIST_BZ_RSN_NM"));
                    dts_Save.setCellData(tmpInt, "TRANSTR_EMP_NO", js_id);
                    dts_Save.setCellData(tmpInt, "USE_YN", 'N');
                    tmpInt++;
                }
            }
            dts_Save.setBroadcast(true, true);
            trs_Save.KeyName = "toinb_dataid4";
            const sbmOptions = {
                id : "sbm_trs_Save",
                action : "/MktActNotice.do",
                ref : "dts_Save",
                target : "trs_Save=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }
    }
};

