///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name listCdSync
 * @description list Cd Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listCdSync = async function() {
    await scwin.searchLeft();
    await scwin.searchRight();
};

/**
 * @method
 * @name cntDatasetRowCheck
 * @description ---------------------------------------------------------------------------- 데이터셋의 체크박스 선택이 되어 있는지 확인하여 참,거짓을 넘겨준다. -------------------------------------------------------------------------------
 * @param {*} sval sval
 * @returns {void}
 * @hidden N
 */
scwin.cntDatasetRowCheck = function(sval) {
    let cCnt = 0;
    for (i = 1; i <= sval.getRowCount(); i++) {
        if (sval.getCellData(i, "CHK_FLAG") === 'T') {
            cCnt++;
        }
    }
    if (cCnt === 0) {
        return false;
    } else {
        return true;
    }
};
